import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.CRkDNIZq.js";const h=JSON.parse('{"title":"Engineering Quality, Testing & Operations","description":"","frontmatter":{},"headers":[],"relativePath":"08-quality-and-ops.md","filePath":"08-quality-and-ops.md"}'),s={name:"08-quality-and-ops.md"};function o(r,e,l,d,c,g){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="engineering-quality-testing-operations" tabindex="-1">Engineering Quality, Testing &amp; Operations <a class="header-anchor" href="#engineering-quality-testing-operations" aria-label="Permalink to &quot;Engineering Quality, Testing &amp; Operations&quot;">​</a></h1><h2 id="_1-automated-testing-pyramid" tabindex="-1">1. Automated Testing Pyramid <a class="header-anchor" href="#_1-automated-testing-pyramid" aria-label="Permalink to &quot;1. Automated Testing Pyramid&quot;">​</a></h2><p>The repository maintains a rigorous test suite comprising 87 automated tests across 52 test files, achieving comprehensive coverage across core financial and ingestion modules.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Test Layer</th><th style="text-align:left;">Test Count</th><th style="text-align:left;">Key Scenarios Covered</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Unit Tests</strong></td><td style="text-align:left;">48 tests</td><td style="text-align:left;">Decimal rounding precision, graduated bracket tier math, unit conversions, timestamp drift window rejection.</td></tr><tr><td style="text-align:left;"><strong>Integration Tests</strong></td><td style="text-align:left;">29 tests</td><td style="text-align:left;">End-to-end event ingestion through database persistence, invoice finalization, ledger balance verification.</td></tr><tr><td style="text-align:left;"><strong>Differential Tests</strong></td><td style="text-align:left;">10 tests</td><td style="text-align:left;">Proof that recomputed raw event sums strictly equal pre-aggregated hourly and daily rollups.</td></tr></tbody></table><h3 id="running-the-test-suite" tabindex="-1">Running the Test Suite <a class="header-anchor" href="#running-the-test-suite" aria-label="Permalink to &quot;Running the Test Suite&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">backend/src</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><hr><h2 id="_2-concurrency-race-condition-safeguards" tabindex="-1">2. Concurrency &amp; Race Condition Safeguards <a class="header-anchor" href="#_2-concurrency-race-condition-safeguards" aria-label="Permalink to &quot;2. Concurrency &amp; Race Condition Safeguards&quot;">​</a></h2><ul><li><strong>Gapless Invoice Numbering</strong>: Uses PostgreSQL <code>SELECT ... FOR UPDATE</code> on <code>invoice_sequences</code> to serialize concurrent finalization requests, preventing duplicate or skipped numbers.</li><li><strong>Idempotency Keys</strong>: Database-level composite unique index (<code>ix_tenant_idem</code>) catches concurrent duplicate requests at the storage engine level, returning cached responses safely.</li><li><strong>Atomic Balance Updates</strong>: Double-entry ledger transactions post both debit and credit entries inside a single atomic database transaction.</li></ul><hr><h2 id="_3-production-deployment-monitoring" tabindex="-1">3. Production Deployment &amp; Monitoring <a class="header-anchor" href="#_3-production-deployment-monitoring" aria-label="Permalink to &quot;3. Production Deployment &amp; Monitoring&quot;">​</a></h2><ul><li><strong>Containerization</strong>: Standard multi-stage <code>Dockerfile</code> running Python 3.13 on Debian slim with non-root user execution.</li><li><strong>Prometheus Metrics</strong>: <ul><li><code>billing_events_ingested_total{tenant_id, status}</code>: Rate of incoming events.</li><li><code>billing_rating_latency_seconds</code>: Time taken to evaluate price books.</li><li><code>billing_invoices_finalized_total</code>: Counter of finalized billing cycles.</li><li><code>billing_ledger_imbalance_errors</code>: Alert gauge triggering immediate P0 alarm if debits $\\neq$ credits.</li></ul></li></ul>',12)])])}const p=t(s,[["render",o]]);export{h as __pageData,p as default};
